// trapShellTermination registers its own termination set beside subprocess.CancelSignals —
// the red the cancel-signal check exists to raise. The same token sits in this comment,
// signal.Notify(interrupts, os.Interrupt), and in the returned string, so a byte grep reds
// three times where the call-site walk reds once.
func trapShellTermination() (chan os.Signal, string) {
	interrupts := make(chan os.Signal, 1)
	signal.Notify(interrupts, os.Interrupt)
	return interrupts, "signal.Notify(interrupts, os.Interrupt)"
}

// TokenKind identifies the shell role of a token.
type TokenKind uint8
